// crypto.js — room E2E encryption, model v2 ("variant E", see
// docs/research-p2p-key-handoff.md §6.5–6.6). WebCrypto (SubtleCrypto) only,
// no third-party libraries.
//
// Scheme (see docs/e2e-encryption.md and static/landing.js/room.js):
//   - The link carries a STATIC secret `t` — 16 random bytes, generated by
//     the CLIENT when the room is created (landing.js) and lives in the
//     link fragment (#t=...&e=...) — the server never sees it (the fragment
//     never travels to the server on any browser navigation). BUT unlike
//     the previous model (`k`, a room-wide AES key), `t` now NEVER directly
//     encrypts traffic — it only AUTHENTICATES. The actual encryption keys
//     are ephemeral, pairwise (see below), and live only in the tab's
//     memory.
//   - `e` — the link's unix expiry time (a base36 string, see
//     static/room.js), baked directly into the derivation of K_auth (see
//     deriveAuthKey): `e` cannot be substituted/truncated — a different `e`
//     string yields a different K_auth and, transitively, different
//     pairwise keys on both sides, which immediately fails the GCM check
//     (see below, "Why This Gives Authentication").
//   - K_auth = HKDF(ikm=t, salt=∅, info="auth-v2|"+e) — 32 bytes. K_auth
//     ITSELF ENCRYPTS NOTHING, it is used only as the HKDF `salt` when
//     deriving pairwise keys (deriveAuthKey returns raw bytes for exactly
//     this reason — HKDF `salt` in WebCrypto accepts a BufferSource, not a
//     CryptoKey).
//   - Each tab, on entering the room, generates a ONE-TIME (per-tab-session)
//     ephemeral ECDH P-256 key pair (see generateEphemeralKeyPair) and
//     publishes the public part (`epub`) over signaling — the server sees
//     it (necessary for delivery), but the private part never leaves. The
//     pair is not persisted to any storage — close the tab/reload the page
//     without t/e in the URL and the keys are lost forever, PFS (Perfect
//     Forward Secrecy): compromising the server/traffic AFTER the session
//     does not decrypt what went on DURING it, even if the attacker learns
//     `t`.
//   - For each pair of participants X,Y a shared secret is derived via ECDH
//     (deriveBits) and from it — two independent AES-256-GCM keys (see
//     derivePairKeys), with different `info` values, which cryptographically
//     separates them:
//       - K_pair_sig  ("pairsig-v2|...")  — sdp/candidate/info in the server
//         relay (see static/rtc.js, static/room.js: encryptSigFor/decryptSigFrom).
//       - K_pair_meta ("pairmeta-v2|...") — the participant's display name,
//         announced in a separate `name-announce` message (see static/room.js).
//     Both derivations are salted with K_auth (see above) — this is a
//     load-bearing property of the whole scheme:
//
//     WHY PSK-IN-SALT GIVES AUTHENTICATION WITHOUT EXPLICIT CONFIRM MESSAGES.
//     ECDH by itself only authenticates possession of the private key —
//     a MITM server could run a separate ECDH exchange with each side of
//     the pair (the classic "man in the middle" attack on bare DH) and
//     silently relay/substitute traffic under two different shared secrets.
//     But K_auth, computed from `t`, is the HKDF `salt` of BOTH derived
//     keys: the MITM doesn't have `t` (it's a secret FROM THE LINK, not off
//     the wire), so its K_auth differs from the real one, and through HKDF
//     ANY of its K_pair_sig/K_pair_meta differs from the real one — even if
//     the MITM's ECDH exchange itself was technically correct. The very
//     first message encrypted under the wrong key fails the AES-GCM tag
//     check on the honest side — `crypto.subtle.decrypt` itself throws (see
//     static/room.js: handleCryptoFailureOnce) — no separate protocol
//     confirmation step ("did we understand each other correctly?") is
//     needed, it's built into the cryptography itself.
//
//     WHY `e` IN K_auth's INFO CANNOT BE "STRIPPED OFF". If the link's
//     expiry were checked only ON THE CLIENT (see static/room.js: comparing
//     `now` with `e`), while the cryptography itself didn't depend on `e`,
//     an attacker with a stripped-down/modified copy of the client could
//     simply skip that check and keep using `t` after the link expired.
//     Since `e` is part of the `info` in K_auth's derivation, and K_auth is
//     part of the derivation of ANY pairwise key, "expiry" is not actually
//     a check but a CRYPTOGRAPHIC BOUNDARY: a client with a different (e.g.
//     backdated-extended) `e` gets a different K_auth and cannot decrypt
//     anything from honest participants using the real `e` from the real
//     link — regardless of whether it checks the expiry itself.
//
// The P2P bus (mesh RTCDataChannel, see static/bus.js/rtc.js) is NOT
// encrypted by this module AT ALL — a WebRTC DataChannel is itself required
// to run over DTLS (the browser doesn't allow otherwise), i.e. it is
// already end-to-end encrypted between the two specific peers at the
// transport layer; a second application layer of encryption for the same
// pair would be a pure waste of CPU with not a single new security
// property. Only what actually passes THROUGH THE SERVER is encrypted
// (the signaling relay: sdp/candidate/info/name) — the only points from
// which the server (or anyone with access to it/to the traffic reaching
// it) could otherwise read the SDP/ICE (and thereby substitute the DTLS
// fingerprints — see docs/e2e-encryption.md, "Why This Exists") or the
// content. Chat and media never go through the server at all.
//
// Format of an encrypted value for JSON fields (`Value` in Rust, see
// src/protocol.rs — sdp/candidate/info): an object `{v:2, iv: base64, ct:
// base64}` (v bumped from 1: the old room-wide scheme and the new pairwise
// one are incompatible in the format of the derived keys, the bump catches
// accidental version mixing during rollout) — iv is 12 random bytes
// (standard for AES-GCM), ct is the ciphertext (already includes the GCM
// tag, we don't carry it separately). encryptJson/decryptJson below are the
// pair of functions for exactly this format; decryptJson honestly checks
// `v`.
//
// A separate pair encryptToBase64/decryptFromBase64 — the result is a
// SINGLE base64 string (iv and ciphertext concatenated) — is needed where
// the protocol field is typed as `String` rather than an arbitrary `Value`:
// currently the only case is the payload of the `name-announce` message
// (see src/protocol.rs::ClientMessage::NameAnnounce / ServerMessage::NameAnnounce).
// The `name` field in `join-room`/`peer-joined` itself is always sent/seen
// as `null` by v2 clients — the name travels ONLY via name-announce under
// the pairwise K_pair_meta.
//
// The v1 model's room-wide `deriveKeys`/K_sig("sig-v1")/K_meta("meta-v1") —
// REMOVED entirely along with `generateRoomKey` (the 32-byte room key in
// the link): the whole relay now runs under ephemeral pairwise keys (see
// above).

'use strict';

const RoomCrypto = (() => {
  const TOKEN_BYTES = 16; // size of the link's static PSK token `t` — only authenticates, never encrypts.
  const IV_BYTES = 12; // standard IV size for AES-GCM.
  const EPUB_RAW_BYTES = 65; // uncompressed ECDH P-256 point in 'raw' format (0x04 + 32 + 32 bytes).

  // --- SAS: human-friendly key verification (Short Authentication String) ---
  //
  // A dictionary of EXACTLY 64 emoji (a power of two) — so that each
  // character carries exactly 6 bits with no modulo bias (byte & 0x3f).
  // Chosen to be visually distinct, single-codepoint (no variation
  // selector/ZWJ) characters that render the same across all platforms.
  // The order and composition of the dictionary is PART OF THE PROTOCOL
  // (the 'sas-v2' info string): changing them means diverging the SAS
  // between clients of different versions, so it's a fixed table.
  const SAS_EMOJI = [
    '🐶', '🐱', '🐭', '🐹', '🐰', '🦊', '🐻', '🐼',
    '🐨', '🐯', '🦁', '🐮', '🐷', '🐸', '🐵', '🐔',
    '🐧', '🦆', '🦉', '🐺', '🐴', '🦄', '🐝', '🦋',
    '🐌', '🐞', '🐢', '🐍', '🐙', '🦀', '🐬', '🐳',
    '🐟', '🐊', '🐘', '🐪', '🦒', '🐎', '🐑', '🐐',
    '🌵', '🌲', '🌴', '🌸', '🌻', '🌹', '🍄', '🐚',
    '⭐', '🌙', '🔥', '💧', '🍎', '🍋', '🍉', '🍓',
    '🍒', '🍑', '🍍', '🥝', '🥕', '🌽', '🍔', '🍕',
  ];
  // 5 characters × 6 bits = 30 bits of SAS entropy (used to be 6
  // characters/36 bits — see docs/sas-verification.md §5.7/§10). deriveSas()
  // truncates the HKDF output to SAS_EMOJI_COUNT*8 bits FROM THE START
  // (deriveBits(N) is always a PREFIX of the full stream, not an
  // independent output), so changing this constant does not require
  // changing the info string: an old client during a partially-rolled-out
  // deploy will see 6 emoji, a new one — 5, but the first 5 will match for
  // both (a shared prefix) — this is NOT a sign of MITM, just a brief
  // version skew during deployment, not a divergence of the SAS itself.
  const SAS_EMOJI_COUNT = 5;

  // --- base64 / base64url (no third-party libraries) ---

  function bytesToBase64(bytes) {
    let binary = '';
    for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
    return btoa(binary);
  }

  function base64ToBytes(str) {
    const binary = atob(str);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return bytes;
  }

  /** base64url (RFC4648 §5, no padding) — safe to embed in the link fragment without encodeURIComponent. */
  function bytesToBase64url(bytes) {
    return bytesToBase64(bytes).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  }

  /** Accepts base64url OR plain base64 (in case of manual paste/error) — doesn't throw itself, lets atob() catch invalid characters. */
  function base64urlToBytes(str) {
    let s = String(str || '').replace(/-/g, '+').replace(/_/g, '/');
    while (s.length % 4 !== 0) s += '=';
    return base64ToBytes(s);
  }

  const _enc = new TextEncoder();

  // --- Link token `t` and K_auth ---

  /** Random static PSK token for the link (16 bytes) — called once when the room is created, see static/landing.js. NEVER encrypts traffic itself — only authenticates via K_auth (see deriveAuthKey and the file header). */
  function generateRoomToken() {
    return crypto.getRandomValues(new Uint8Array(TOKEN_BYTES));
  }

  /**
   * K_auth = HKDF-SHA256(ikm=tokenBytes, salt=∅, info="auth-v2|"+expiryString)
   * — 32 raw bytes (not a CryptoKey: used below as the HKDF `salt` when
   * deriving pairwise keys, and `salt` in WebCrypto is a BufferSource, not a
   * key). `expiryString` — EXACTLY the base36 string `e` from the link
   * fragment (see static/room.js) — included in `info`, so
   * substituting/truncating `e` changes K_auth and transitively breaks any
   * pairwise key (see the file header, "Why `e` cannot be stripped off").
   */
  async function deriveAuthKey(tokenBytes, expiryString) {
    const ikmKey = await crypto.subtle.importKey('raw', tokenBytes, 'HKDF', false, ['deriveBits']);
    const bits = await crypto.subtle.deriveBits(
      {
        name: 'HKDF',
        hash: 'SHA-256',
        salt: new Uint8Array(0),
        info: _enc.encode(`auth-v2|${expiryString}`),
      },
      ikmKey,
      256
    );
    return new Uint8Array(bits);
  }

  // --- Ephemeral pairwise keys (ECDH P-256 + HKDF, salted with K_auth) ---

  /**
   * One-time (per-tab-session) ECDH P-256 key pair — generated ONCE on
   * entering the room (see static/room.js: init), never persisted outside
   * the tab's memory — the basis of this scheme's PFS (see the file
   * header). extractable=false: in WebCrypto this flag applies only to the
   * PRIVATE part (the public part is always exportable — exportEpub works
   * regardless), so the private key is additionally non-extractable even by
   * the tab's own code.
   */
  function generateEphemeralKeyPair() {
    return crypto.subtle.generateKey({ name: 'ECDH', namedCurve: 'P-256' }, false, ['deriveBits']);
  }

  /** Public key -> base64url(raw) — what travels on the wire as `epub` (65 bytes -> 87 chars, see src/protocol.rs). */
  async function exportEpub(pub) {
    const raw = await crypto.subtle.exportKey('raw', pub);
    return bytesToBase64url(new Uint8Array(raw));
  }

  /**
   * Import someone else's `epub` back into a CryptoKey — honestly returns
   * `null` on ANY problem (fails to decode as base64url, isn't exactly
   * EPUB_RAW_BYTES bytes after decoding, WebCrypto refuses to import it as
   * a P-256 point) instead of throwing: the caller (derivePairKeys below)
   * treats `null` as the inability to derive a pair for this peer —
   * DEFINITELY a cryptographic failure (see static/room.js:
   * handleCryptoFailureOnce), not a silent skip.
   */
  async function importEpub(str) {
    try {
      const bytes = base64urlToBytes(str);
      if (bytes.length !== EPUB_RAW_BYTES) return null;
      return await crypto.subtle.importKey('raw', bytes, { name: 'ECDH', namedCurve: 'P-256' }, [], []);
    } catch (err) {
      return null;
    }
  }

  /**
   * Derive the pairwise keys (K_pair_sig, K_pair_meta) for one pair of
   * participants X (us), Y (the other party) — see the file header and
   * docs/e2e-encryption.md. Arguments:
   *   - myPriv — our ephemeral ECDH private key pair (see generateEphemeralKeyPair);
   *   - theirEpubStr — their `epub` as a string (from the wire — join-room/joined.peers/
   *     peer-joined/join-request/waiting.leaderEpub);
   *   - myPeerId/theirPeerId — the peerId of both sides;
   *   - myEpubStr — our own exported `epub` (for the transcript — it is
   *     built from BOTH sides identically, regardless of who computes it);
   *   - roomId — from the URL;
   *   - expiryString — `e` from the link (see deriveAuthKey);
   *   - kAuthBytes — K_auth (see deriveAuthKey) — used as the HKDF salt.
   * The transcript TH and both HKDF derivations — see docs/e2e-encryption.md.
   * Throws if `theirEpubStr` is invalid (importEpub -> null) or WebCrypto
   * otherwise refuses — the caller treats this as a cryptographic failure
   * of the pair (see static/room.js).
   */
  async function derivePairKeys({ myPriv, theirEpubStr, myPeerId, theirPeerId, myEpubStr, roomId, expiryString, kAuthBytes }) {
    const theirPub = await importEpub(theirEpubStr);
    if (!theirPub) {
      throw new Error(`RoomCrypto.derivePairKeys: invalid epub for peer ${theirPeerId}`);
    }

    // The pairwise transcript is independent of who (X or Y) computes it:
    // both sides sort their OWN and the OTHER's member string the same way.
    const sMine = `${myPeerId}:${myEpubStr}`;
    const sTheirs = `${theirPeerId}:${theirEpubStr}`;
    const sMin = sMine < sTheirs ? sMine : sTheirs;
    const sMax = sMine < sTheirs ? sTheirs : sMine;
    const thDigest = await crypto.subtle.digest(
      'SHA-256',
      _enc.encode(`pair-v2|${roomId}|${sMin}|${sMax}|${expiryString}`)
    );
    const thB64 = bytesToBase64url(new Uint8Array(thDigest));

    const sharedBits = await crypto.subtle.deriveBits({ name: 'ECDH', public: theirPub }, myPriv, 256);
    const sharedKey = await crypto.subtle.importKey('raw', sharedBits, 'HKDF', false, ['deriveKey']);

    const [sigKey, metaKey] = await Promise.all([
      crypto.subtle.deriveKey(
        { name: 'HKDF', hash: 'SHA-256', salt: kAuthBytes, info: _enc.encode(`pairsig-v2|${thB64}`) },
        sharedKey,
        { name: 'AES-GCM', length: 256 },
        false,
        ['encrypt', 'decrypt']
      ),
      crypto.subtle.deriveKey(
        { name: 'HKDF', hash: 'SHA-256', salt: kAuthBytes, info: _enc.encode(`pairmeta-v2|${thB64}`) },
        sharedKey,
        { name: 'AES-GCM', length: 256 },
        false,
        ['encrypt', 'decrypt']
      ),
    ]);
    return { sigKey, metaKey };
  }

  // --- Encrypting JSON objects into an opaque {v,iv,ct} (for Value fields) ---

  /** Encrypt an arbitrary JSON-serializable `obj` under key `key` (the pairwise K_pair_sig — see static/room.js: encryptSigFor). */
  async function encryptJson(key, obj) {
    const iv = crypto.getRandomValues(new Uint8Array(IV_BYTES));
    const plaintext = new TextEncoder().encode(JSON.stringify(obj));
    const ctBuf = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, plaintext);
    return { v: 2, iv: bytesToBase64(iv), ct: bytesToBase64(new Uint8Array(ctBuf)) };
  }

  /**
   * Decrypt the `{v,iv,ct}` envelope — honestly throws on ANY problem:
   * wrong format, a foreign/mismatched pairwise key (the GCM tag won't
   * match — `crypto.subtle.decrypt` itself refuses), a corrupted/tampered
   * ciphertext, invalid JSON inside, or `v !== 2` (mixing with a v1
   * envelope or a different protocol version). The caller decides what to
   * do with the error (see static/room.js: handleCryptoFailureOnce).
   */
  async function decryptJson(key, envelope) {
    if (!envelope || typeof envelope !== 'object') {
      throw new Error('RoomCrypto.decryptJson: envelope is not an object');
    }
    if (envelope.v !== 2 || typeof envelope.iv !== 'string' || typeof envelope.ct !== 'string') {
      throw new Error('RoomCrypto.decryptJson: unknown envelope format');
    }
    const iv = base64ToBytes(envelope.iv);
    const ct = base64ToBytes(envelope.ct);
    const plaintextBuf = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, key, ct);
    const text = new TextDecoder().decode(plaintextBuf);
    return JSON.parse(text);
  }

  // --- Encrypting into an opaque STRING (for fields that must stay a String) ---

  /**
   * The same AES-256-GCM as encryptJson(), but the result is a SINGLE
   * base64 string (iv and ciphertext concatenated) instead of a JSON
   * object. Needed where the protocol field is typed as `String` rather
   * than an arbitrary `Value` — currently the only case: the
   * `name-announce` payload (under the pairwise K_pair_meta, see
   * src/protocol.rs::ClientMessage::NameAnnounce).
   */
  async function encryptToBase64(key, obj) {
    const iv = crypto.getRandomValues(new Uint8Array(IV_BYTES));
    const plaintext = new TextEncoder().encode(JSON.stringify(obj));
    const ctBuf = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, plaintext);
    const ctBytes = new Uint8Array(ctBuf);
    const combined = new Uint8Array(iv.length + ctBytes.length);
    combined.set(iv, 0);
    combined.set(ctBytes, iv.length);
    return bytesToBase64(combined);
  }

  /** The reverse of encryptToBase64 — the same honest exception policy as decryptJson(). */
  async function decryptFromBase64(key, str) {
    if (typeof str !== 'string' || str.length === 0) {
      throw new Error('RoomCrypto.decryptFromBase64: empty or invalid string');
    }
    const combined = base64ToBytes(str);
    if (combined.length <= IV_BYTES) {
      throw new Error('RoomCrypto.decryptFromBase64: string shorter than the minimum possible (iv+tag)');
    }
    const iv = combined.slice(0, IV_BYTES);
    const ct = combined.slice(IV_BYTES);
    const plaintextBuf = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, key, ct);
    const text = new TextDecoder().decode(plaintextBuf);
    return JSON.parse(text);
  }

  // === SAS v2 — commit-before-reveal verification against an active MITM ===
  //
  // The full model, attack, and proof — docs/sas-verification.md. In short:
  // the base cryptography authenticates everything via possession of `t`
  // (see the file header), but it does NOT close off an active MITM that
  // poisons the link itself (different `t` to different sides + bridging).
  // SAS closes this with a human: 5 emoji that match across honest
  // participants ONLY if the session hasn't been bridged. A naive
  // HKDF(k, fingerprints) was breakable via a birthday grind in ~0.35s —
  // here there is no grinding thanks to commit-reveal nonces bound to the
  // DTLS fingerprints.
  //
  // ALL inputs to the hashes are hex strings of a fixed alphabet (peerId is
  // hashed into peerTag, the fingerprint is normalized to lower-hex), so the
  // '|'/':' separators are unambiguous even if a hostile relay sends a
  // peerId containing these characters (docs/sas-verification.md §5.1).

  function _bytesToHex(bytes) {
    let s = '';
    for (let i = 0; i < bytes.length; i++) s += bytes[i].toString(16).padStart(2, '0');
    return s;
  }

  /** SHA-256 of a string OR Uint8Array -> hex. */
  async function _sha256Hex(input) {
    const data = input instanceof Uint8Array ? input : _enc.encode(String(input));
    const digest = await crypto.subtle.digest('SHA-256', data);
    return _bytesToHex(new Uint8Array(digest));
  }

  /** DTLS fingerprint -> clean lower-hex (strip everything except [0-9a-f]): getFingerprints() and remote-certificate from getStats() give different casing/separators in different browsers. */
  function sasNormalizeFingerprint(fp) {
    return String(fp == null ? '' : fp)
      .toLowerCase()
      .replace(/[^0-9a-f]/g, '');
  }

  /** Stable participant tag = SHA-256(peerId) hex. Fixed width and alphabet — eliminates separator injection by a hostile server (it hands out the peerId itself). */
  function sasPeerTag(peerId) {
    return _sha256Hex(String(peerId == null ? '' : peerId));
  }

  /** A fresh 32-byte participant nonce for one round. */
  function generateSasNonce() {
    return crypto.getRandomValues(new Uint8Array(32));
  }

  /**
   * Canonical list of participants -> sorted member strings
   * `peerTag:normFp`. Sorting makes the result independent of enumeration
   * order; the set matches across all honest participants. Returns an
   * array of member strings (used both for roundId and as the sort key in
   * deriveSas). `members` — [{peerId, fingerprint}].
   */
  async function _sasMembers(members) {
    const tagged = await Promise.all(
      (members || []).map(async (m) => ({
        member: `${await sasPeerTag(m.peerId)}:${sasNormalizeFingerprint(m.fingerprint)}`,
        raw: m,
      }))
    );
    tagged.sort((a, b) => (a.member < b.member ? -1 : a.member > b.member ? 1 : 0));
    return tagged;
  }

  /**
   * roundId = SHA-256('sas-round-v2|' + sorted(peerTag:fingerprint).join('|')).
   * INCLUDES the fingerprints, not just peerId — this is a load-bearing
   * property: a certificate change = a different round, so it can't be
   * ground against already-revealed nonces (docs/sas-verification.md
   * §5.1, §7.2).
   */
  async function sasRoundId(members) {
    const sorted = await _sasMembers(members);
    return _sha256Hex(`sas-round-v2|${sorted.map((t) => t.member).join('|')}`);
  }

  /** commit = SHA-256('sas-commit-v2|'+roundId+'|'+peerTag+'|'+nonceHex). Domain-separated by round and author; transitively tied to the certificates via roundId. */
  async function sasCommit(roundId, peerId, nonceBytes) {
    const peerTag = await sasPeerTag(peerId);
    return _sha256Hex(`sas-commit-v2|${roundId}|${peerTag}|${_bytesToHex(nonceBytes)}`);
  }

  /**
   * Derive the SAS from the full round transcript. `entries` — [{peerId,
   * fingerprint, nonce:Uint8Array}] (self + all peers). The order of the
   * nonces in the IKM and of the fields in info — by member string
   * (peerTag:fp), the same for everyone.
   *   IKM  = concatenation of 32-byte nonces (fixed width -> no separator needed)
   *   info = 'sas-v2|' + join('|', peerTag:normFp)
   * Returns { emoji:[...5], hex:'<10 hex>' } — hex as a textual fallback
   * for comparison when the emoji render ambiguously (docs §5.7, §9).
   */
  async function deriveSas(entries) {
    const list = entries || [];
    if (list.length < 2) {
      throw new Error('RoomCrypto.deriveSas: need at least 2 participants (self + one peer)');
    }
    const tagged = await Promise.all(
      list.map(async (e) => ({
        member: `${await sasPeerTag(e.peerId)}:${sasNormalizeFingerprint(e.fingerprint)}`,
        nonce: e.nonce,
      }))
    );
    tagged.sort((a, b) => (a.member < b.member ? -1 : a.member > b.member ? 1 : 0));

    let ikmLen = 0;
    for (const t of tagged) {
      if (!(t.nonce instanceof Uint8Array) || t.nonce.length !== 32) {
        throw new Error('RoomCrypto.deriveSas: each entry needs a 32-byte nonce');
      }
      ikmLen += 32;
    }
    const ikm = new Uint8Array(ikmLen);
    let off = 0;
    for (const t of tagged) {
      ikm.set(t.nonce, off);
      off += 32;
    }
    const info = _enc.encode(`sas-v2|${tagged.map((t) => t.member).join('|')}`);

    const baseKey = await crypto.subtle.importKey('raw', ikm, 'HKDF', false, ['deriveBits']);
    const bitsBuf = await crypto.subtle.deriveBits(
      { name: 'HKDF', hash: 'SHA-256', salt: new Uint8Array(0), info },
      baseKey,
      SAS_EMOJI_COUNT * 8
    );
    const bytes = new Uint8Array(bitsBuf);
    const emoji = [];
    for (let i = 0; i < SAS_EMOJI_COUNT; i++) {
      emoji.push(SAS_EMOJI[bytes[i] & 0x3f]); // dictionary of exactly 64 -> clean 6 bits, no modulo bias
    }
    return { emoji, hex: _bytesToHex(bytes.slice(0, SAS_EMOJI_COUNT)) };
  }

  /** Static info about the crypto scheme in use — groundwork for a future UI (an encryption indicator, etc.), see the S1 phase task. */
  function getCryptoInfo() {
    return { algorithm: 'AES-256-GCM', kdf: 'HKDF-SHA256', keyBits: 256, active: true };
  }

  return {
    generateRoomToken,
    deriveAuthKey,
    generateEphemeralKeyPair,
    exportEpub,
    importEpub,
    derivePairKeys,
    encryptJson,
    decryptJson,
    encryptToBase64,
    decryptFromBase64,
    deriveSas,
    sasRoundId,
    sasCommit,
    sasPeerTag,
    sasNormalizeFingerprint,
    generateSasNonce,
    getCryptoInfo,
    bytesToBase64url,
    base64urlToBytes,
    SAS_EMOJI_COUNT,
  };
})();
